-- Preflight for migration 0032 (db constraints). READ-ONLY: SELECT statements only, safe on prod.
-- Every violating_rows value must be 0 before pushing the migration.
-- Run in psql or the Neon SQL editor.
-- A CHECK passes when its expression is NULL, so each test is NOT COALESCE((expr), true).

SELECT 'ck_fixed_deposits_principal_positive' AS constraint_name, count(*) AS violating_rows FROM fixed_deposits WHERE NOT COALESCE((principal > 0), true)
UNION ALL SELECT 'ck_fixed_deposits_rate_range', count(*) FROM fixed_deposits WHERE NOT COALESCE((rate >= 0 AND rate <= 100), true)
UNION ALL SELECT 'ck_fixed_deposits_tenure_positive', count(*) FROM fixed_deposits WHERE NOT COALESCE((tenure_years + tenure_months + tenure_days > 0), true)
UNION ALL SELECT 'ck_recurring_deposits_instalment_positive', count(*) FROM recurring_deposits WHERE NOT COALESCE((monthly_instalment > 0), true)
UNION ALL SELECT 'ck_recurring_deposits_rate_range', count(*) FROM recurring_deposits WHERE NOT COALESCE((rate >= 0 AND rate <= 100), true)
UNION ALL SELECT 'ck_recurring_deposits_tenure_positive', count(*) FROM recurring_deposits WHERE NOT COALESCE((tenure_years + tenure_months + tenure_days > 0), true)
UNION ALL SELECT 'ck_stocks_quantity_positive', count(*) FROM stocks WHERE NOT COALESCE((quantity > 0), true)
UNION ALL SELECT 'ck_stocks_avg_buy_price_positive', count(*) FROM stocks WHERE NOT COALESCE((avg_buy_price > 0), true)
UNION ALL SELECT 'ck_bonds_quantity_positive', count(*) FROM bonds WHERE NOT COALESCE((quantity > 0), true)
UNION ALL SELECT 'ck_bonds_purchase_price_positive', count(*) FROM bonds WHERE NOT COALESCE((purchase_price > 0), true)
UNION ALL SELECT 'ck_bonds_invested_nonnegative', count(*) FROM bonds WHERE NOT COALESCE((invested_amount >= 0), true)
UNION ALL SELECT 'ck_bonds_face_value_positive', count(*) FROM bonds WHERE NOT COALESCE((face_value IS NULL OR face_value > 0), true)
UNION ALL SELECT 'ck_bonds_maturity_after_purchase', count(*) FROM bonds WHERE NOT COALESCE((maturity_date > purchase_date), true)
UNION ALL SELECT 'ck_mutual_funds_units_positive', count(*) FROM mutual_funds WHERE NOT COALESCE((units > 0), true)
UNION ALL SELECT 'ck_mutual_funds_avg_nav_nonnegative', count(*) FROM mutual_funds WHERE NOT COALESCE((avg_nav >= 0), true)
UNION ALL SELECT 'ck_mutual_funds_invested_nonnegative', count(*) FROM mutual_funds WHERE NOT COALESCE((invested_amount >= 0), true)
UNION ALL SELECT 'ck_nps_holdings_units_positive', count(*) FROM nps_holdings WHERE NOT COALESCE((units > 0), true)
UNION ALL SELECT 'ck_nps_holdings_contributed_nonnegative', count(*) FROM nps_holdings WHERE NOT COALESCE((contributed >= 0), true)
UNION ALL SELECT 'ck_gold_holdings_weight_positive', count(*) FROM gold_holdings WHERE NOT COALESCE((weight_grams > 0), true)
UNION ALL SELECT 'ck_gold_holdings_invested_nonnegative', count(*) FROM gold_holdings WHERE NOT COALESCE((invested_amount >= 0), true)
UNION ALL SELECT 'ck_cash_holdings_balance_nonnegative', count(*) FROM cash_holdings WHERE NOT COALESCE((balance >= 0), true)
UNION ALL SELECT 'ck_cash_holdings_rate_range', count(*) FROM cash_holdings WHERE NOT COALESCE((interest_rate IS NULL OR (interest_rate >= 0 AND interest_rate <= 100)), true)
UNION ALL SELECT 'ck_pf_holdings_balance_nonnegative', count(*) FROM pf_holdings WHERE NOT COALESCE((balance >= 0), true)
UNION ALL SELECT 'ck_pf_holdings_rate_range', count(*) FROM pf_holdings WHERE NOT COALESCE((interest_rate >= 0 AND interest_rate <= 100), true)
UNION ALL SELECT 'ck_pf_holdings_contributed_nonnegative', count(*) FROM pf_holdings WHERE NOT COALESCE((contributed IS NULL OR contributed >= 0), true)
UNION ALL SELECT 'ck_other_holdings_value_nonnegative', count(*) FROM other_holdings WHERE NOT COALESCE((current_value >= 0), true)
UNION ALL SELECT 'ck_other_holdings_invested_nonnegative', count(*) FROM other_holdings WHERE NOT COALESCE((invested_amount IS NULL OR invested_amount >= 0), true)
UNION ALL SELECT 'ck_other_holdings_acquired_before_value', count(*) FROM other_holdings WHERE NOT COALESCE((acquired_on IS NULL OR acquired_on <= value_date), true)
UNION ALL SELECT 'ck_holding_exits_quantity_positive', count(*) FROM holding_exits WHERE NOT COALESCE((quantity IS NULL OR quantity > 0), true)
UNION ALL SELECT 'ck_holding_exits_amount_nonnegative', count(*) FROM holding_exits WHERE NOT COALESCE((amount >= 0), true)
UNION ALL SELECT 'ck_holding_exits_cost_nonnegative', count(*) FROM holding_exits WHERE NOT COALESCE((cost >= 0), true)
UNION ALL SELECT 'ck_holding_exits_charges_nonnegative', count(*) FROM holding_exits WHERE NOT COALESCE((charges >= 0), true)
UNION ALL SELECT 'ck_holding_fundings_amount_positive', count(*) FROM holding_fundings WHERE NOT COALESCE((amount > 0), true)
UNION ALL SELECT 'ck_mf_sips_amount_positive', count(*) FROM mf_sips WHERE NOT COALESCE((amount > 0), true)
UNION ALL SELECT 'ck_mf_sips_end_after_start', count(*) FROM mf_sips WHERE NOT COALESCE((end_date IS NULL OR end_date >= start_date), true)
UNION ALL SELECT 'ck_mf_transactions_amount_positive', count(*) FROM mf_transactions WHERE NOT COALESCE((amount > 0), true)
UNION ALL SELECT 'ck_mf_transactions_units_positive', count(*) FROM mf_transactions WHERE NOT COALESCE((units > 0), true)
UNION ALL SELECT 'uq_holding_fundings_active', count(*) FROM (SELECT 1 FROM holding_fundings WHERE refunded_at IS NULL GROUP BY asset_type, holding_id HAVING count(*) > 1) t;
